fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    let length = dst.len();
    let mut result = Vec::with_capacity(length);

    for i in 0..length {
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }

    result
}